/** FNV-1a 32 bits (offset basis 0x811C9DC5, prime 0x01000193) of the code points of a lowercased text. */
export function fnv1a(text: string): number {
  let hash = 0x811c9dc5;
  for (const char of text.toLowerCase()) {
    hash ^= char.codePointAt(0)!;
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash;
}

/** The hue (HSL, 0 to 359, rounded) of a "#RRGGBB": the hue of the accent of a universe, for monogramColor. */
export function hueOfColor(hex: string): number {
  const [r, g, b] = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255);
  const max = Math.max(r, g, b), min = Math.min(r, g, b), d = max - min;
  if (d === 0) return 0;
  const h = max === r ? ((g - b) / d) % 6 : max === g ? (b - r) / d + 2 : (r - g) / d + 4;
  return ((Math.round(h * 60) % 360) + 360) % 360;
}

/** [r, g, b] (0–255, rounded) of an HSL color, as CSS. */
function rgbOfHsl(h: number, s: number, l: number): [number, number, number] {
  const a = s * Math.min(l, 1 - l);
  const f = (n: number) => { const k = (n + h / 30) % 12; return Math.round(255 * (l - a * Math.max(-1, Math.min(k - 3, 9 - k, 1)))); };
  return [f(0), f(8), f(4)];
}
/** WCAG relative luminance of [r, g, b]. */
function luminanceOf([r, g, b]: [number, number, number]): number {
  const c = (v: number) => { const x = v / 255; return x <= 0.03928 ? x / 12.92 : ((x + 0.055) / 1.055) ** 2.4; };
  return 0.2126 * c(r) + 0.7152 * c(g) + 0.0722 * c(b);
}

/**
 * The monogram of an author (since v4.0.0): one lightness step per account (FNV-1a 32 of its id modulo the steps)
 * within the hue of the accent of the universe (hueOfColor), under the ink of the mode: the HSL lightness at which
 * the color reaches the luminance of the step (20 halvings). README § Monograms; test vectors there.
 */
export function monogramColor(universeHue: number, accountId: string, mode: Mode): { step: number; background: string; ink: string } {
  const m = monograms[mode];
  const step = fnv1a(accountId) % m.steps;
  let lo = 0, hi = 1;
  for (let i = 0; i < 20; i++) {
    const mid = (lo + hi) / 2;
    if (luminanceOf(rgbOfHsl(universeHue, m.saturation, mid)) < m.luminance[step]) lo = mid; else hi = mid;
  }
  const background = `#${rgbOfHsl(universeHue, m.saturation, m.above ? hi : lo).map((c) => c.toString(16).padStart(2, '0')).join('').toUpperCase()}`;
  return { step, background, ink: m.ink };
}

