/** @deprecated since v3.0.0: the fallback of a monogram without a theme only. The hue (0–359): FNV-1a 32 over the code points of the lowercased canonical name ("%paris"), modulo 360. */
export function hueOf(name: string): number {
  let hash = 0x811c9dc5;
  for (const char of name.toLowerCase()) {
    hash ^= char.codePointAt(0)!;
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash % 360;
}

/** @deprecated since v3.0.0: the fallback of a monogram without a theme only. The colors, as CSS: a style prop ({ background, color }). */
export function badgeColors(name: string, mode: Mode, style: BadgeStyle = 'solid'): { background: string; color: string } {
  const hue = hueOf(name);
  const { background: b, foreground: f } = badges[mode][style];
  const hsl = (s: number, l: number) => `hsl(${hue} ${Math.round(s * 1000) / 10}% ${Math.round(l * 1000) / 10}%)`;
  return { background: hsl(b.saturation, b.lightness), color: hsl(f.saturation, f.lightness) };
}
